closestTo.example:
kcds.core.Events.on('playerCommand', async (player, command) => {
  if (command !== 'lock') {
    return;
  }
  const { found, door } = await kcds.world.Door.closestTo(player);
  if (found) {
    door.locked = true;
  }
});

closestTo.exampleCs:
Events.On("playerCommand", async (Player player, string command) =>
{
    if (command != "lock")
    {
        return;
    }
    var result = await Door.ClosestTo(player);
    if (result["found"])
    {
        result["door"].Set("locked", true);
    }
});

